 await test('primitive native list items remain scalar while their input purposes are editable objects',async()=>{const scope={bindings:[],regions:[{id:'primitive_list',target:'/document/labels',start:0,count:0,source:'/labels',kind:'repeat',max_items:4,prototype:{native:['Original label'],bindings:[],regions:[]}}]},nativeField={target:'/0',label:'Label',format:'text',writable:true,current_value:'Original label'},binding=ui.assignRole(scope.regions[0].prototype,nativeField,'custom','list','Label');binding.instructions='Write one concise label.';const input=ui.seedScope(scope,2,0,{}, {regionMeta:{primitive_list:{fields:[nativeField],limits:{min_items:0,max_items:4}}}});assert.equal(input.labels.length,2);assert.equal(ui.contentValue(input.labels[0],binding.source),'Original label');assert.deepEqual(scope.regions[0].prototype.native,['Original label']);});
 await test('generic registered strings can become rich text or links while native choice formats stay fixed',async()=>{const owner={bindings:[]},field={target:'/document/custom_content',label:'Custom category content',format:'text',writable:true,allowed_formats:['text','html','url']};assert(ui.rolesFor(field).some(role=>role.id==='rich_text'));assert(ui.rolesFor(field).some(role=>role.id==='link_url'));let binding=ui.assignRole(owner,field,'rich_text','category');assert.equal(binding.format,'html');binding=ui.assignRole(owner,field,'link_url','category');assert.equal(binding.format,'url');assert.equal(owner.bindings.length,1);binding=ui.assignRole(owner,field,'custom','category','Custom purpose');assert.equal(binding.format,'text');const choice={target:'/document/style',label:'Style',format:'text',writable:true,constraints:{type:'string',enum:['wide','narrow']}};assert(!ui.rolesFor(choice).some(role=>role.id==='link_url'));assert.throws(()=>ui.assignRole(owner,choice,'link_url','category'));assert.equal(ui.assignRole(owner,choice,'rich_text','category').format,'text');const nativeUrl={...choice,target:'/document/link',format:'url',constraints:{type:'string',format:'uri-reference'}};assert(!ui.rolesFor(nativeUrl).some(role=>role.id==='rich_text'));assert.equal(ui.assignRole(owner,nativeUrl,'link_url','category').format,'url');});
 await test('JSON-backed button lists require explicit structured confirmation and preserve their storage codec',async()=>{const key='_inspace_wc_cat_buttons',schema={type:'array','x-nova-storage':'json',items:{type:'object',additionalProperties:false,properties:{label:{type:'string'},url:{type:'string',format:'uri-reference'}}}},raw='[{"label":"Get advice","url":"https://site.example/contact/"}]';const t=await categoryMounted({request:async(path,payload,current)=>{if(path==='/design'){current.blueprint.document.original_buttons=raw;current.excluded_fields=[{key,label:'Category buttons',declaration_required:true,value_type:'array',storage_hint:'json',suggested_schema:clone(schema)}];if(payload.declared_term_fields){assert.deepEqual(payload.declared_term_fields,{[key]:schema});current.declared_term_fields=clone(payload.declared_term_fields);current.excluded_fields=[];current.blueprint.document.buttons=JSON.parse(raw);current.containers=[{target:'/document/buttons',label:'Category buttons',items:[{index:0,label:'Button 1'}]}];current.source_receipt='json-buttons-confirmed';}return current;}}});t.controller.next();await t.controller.capture(18);assert(t.host.textContent.includes('stores its content together as JSON text'));assert(t.host.textContent.includes('Each item › label: text'));assert(t.host.textContent.includes('Each item › url: link'));const type=controlFor(t,'Content type for Category buttons');assert.equal(type.value,'structured');assert.deepEqual(type.children.map(item=>item.value),['structured']);assert.equal(t.controller.state.design.blueprint.document.original_buttons,raw);assert.equal(t.calls.filter(item=>item.path==='/design').length,1);const button=t.host.all().find(item=>item.tag==='button'&&item.ownText==='Use as content field');button.events.click();await new Promise(resolve=>setImmediate(resolve));assert.equal(t.controller.state.error,false);const call=t.calls.filter(item=>item.path==='/design')[1].payload;assert.deepEqual(call.declared_term_fields[key],schema);assert.equal(call.existing_blueprint.document.original_buttons,raw);assert.equal(t.controller.state.design.source_receipt,'json-buttons-confirmed');assert.equal(t.controller.state.recipe.blueprint.document.original_buttons,raw);assert.deepEqual(t.controller.state.recipe.blueprint.document.buttons,[{label:'Get advice',url:'https://site.example/contact/'}]);});
 await test('unavailable custom fields keep complete diagnostics without duplicating fixed design controls',async()=>{const t=await categoryMounted({request:async(path,payload,current)=>{if(path==='/design'){current.excluded_fields=[{key:'legacy_intro',label:'Legacy introduction',declaration_required:true,value_type:'string',reason:'Confirm this existing editorial field.'},{key:'unsupported_shape',label:'Unsupported custom list',reason:'This list has no supported item definition.'}];current.fields.push(...current.excluded_fields.map((field,index)=>({target:'/term_fields/unavailable/'+index,label:field.label,writable:false,protected:true,custom_field_key:field.key,reason:field.reason})));return current;}}});t.controller.next();await t.controller.capture(18);assert(t.host.textContent.includes('Additional fields needing confirmation'));assert(t.host.textContent.includes('Confirm this existing editorial field.'));assert(t.host.textContent.includes('Custom fields that need a supported definition'));assert(t.host.textContent.includes('This list has no supported item definition.'));assert.equal(t.host.all().filter(item=>item.tag==='summary'&&item.ownText.includes('fixed design controls')).length,0);assert.equal((t.host.textContent.match(/This list has no supported item definition\./g)||[]).length,1);assert.equal(controlFor(t,'Content type for Legacy introduction').value,'text');});
 await test('PHP empty declaration arrays become objects and two browser confirmations survive JSON serialization',async()=>{const wireRequests=[],introKey='_legacy_intro',buttonsKey='_legacy_buttons',buttonSchema={type:'array','x-nova-storage':'json',items:{type:'object',additionalProperties:false,properties:{label:{type:'string'},url:{type:'string',format:'uri-reference'}}}};const t=await categoryMounted({request:async(path,payload,current)=>{if(path==='/design'){const wire=JSON.parse(JSON.stringify(payload));wireRequests.push(wire);current.declared_term_fields=[];current.excluded_fields=[{key:introKey,label:'Legacy top copy',declaration_required:true,value_type:'string'},{key:buttonsKey,label:'Legacy buttons',declaration_required:true,value_type:'array',storage_hint:'json',suggested_schema:clone(buttonSchema)}];if(wire.declared_term_fields){assert.equal(Array.isArray(wire.declared_term_fields),false);current.declared_term_fields=Object.fromEntries(Object.entries(wire.declared_term_fields).map(([key,schema])=>[key,Object.fromEntries(Object.entries(schema).reverse())]));current.excluded_fields=current.excluded_fields.filter(item=>!Object.hasOwn(current.declared_term_fields,item.key));current.blueprint.term_fields={local_declarations:clone(current.declared_term_fields)};Object.keys(current.declared_term_fields).forEach(key=>current.fields.push({target:'/term_fields/values/'+key,label:key,writable:true,format:key===introKey?'html':'text',custom_field_key:key}));const count=Object.keys(current.declared_term_fields).length;current.seal='confirmed-seal-'+count;current.source_receipt='confirmed-source-'+count;current.source_reference.native_digest=(count===1?'b':'c').repeat(64);current.visual_preview.digest=current.source_reference.native_digest;}return current;}}});t.controller.next();await t.controller.capture(18);assert.equal(Array.isArray(t.controller.state.design.declared_term_fields),false);assert.deepEqual(t.controller.state.declaredTermFields,{});choosePurpose(t,'title');const binding=clone(t.controller.state.recipe.bindings[0]);t.controller.state.id='00000000-0000-4000-8000-000000000018';t.controller.state.revision=8;const introType=controlFor(t,'Content type for Legacy top copy');introType.value='html';introType.events.change();let use=t.host.all().find(item=>item.tag==='button'&&item.ownText==='Use as content field'&&item.parentNode.textContent.includes('Legacy top copy'));use.events.click();await new Promise(resolve=>setImmediate(resolve));assert.equal(t.controller.state.error,false);assert.deepEqual(wireRequests[1].declared_term_fields,{[introKey]:{type:'string',format:'html'}});use=t.host.all().find(item=>item.tag==='button'&&item.ownText==='Use as content field'&&item.parentNode.textContent.includes('Legacy buttons'));use.events.click();await new Promise(resolve=>setImmediate(resolve));assert.equal(t.controller.state.error,false);assert.deepEqual(wireRequests[2].declared_term_fields,{[introKey]:{format:'html',type:'string'},[buttonsKey]:buttonSchema});assert.equal(wireRequests[2].source_receipt,'confirmed-source-1');assert.equal(wireRequests[2].existing_seal,'confirmed-seal-1');assert.deepEqual(Object.keys(t.controller.state.declaredTermFields).sort(),[buttonsKey,introKey].sort());assert.equal(t.controller.state.declaredTermFields[buttonsKey]['x-nova-storage'],'json');assert.deepEqual(t.controller.state.recipe.bindings,[binding]);assert.equal(t.controller.state.id,'00000000-0000-4000-8000-000000000018');assert.equal(t.controller.state.revision,8);});
 await test('custom confirmation refuses silent no-op and altered returned storage definitions',async()=>{let altered=false;const schema={type:'array','x-nova-storage':'json',items:{type:'string'}},key='_encoded_content',t=await categoryMounted({request:async(path,payload,current)=>{if(path==='/design'){current.declared_term_fields=[];current.excluded_fields=[{key,label:'Encoded content',declaration_required:true,value_type:'array',storage_hint:'json',suggested_schema:clone(schema)}];if(payload.declared_term_fields&&altered){current.declared_term_fields={[key]:{type:'array',items:{type:'string'}}};current.fields.push({target:'/term_fields/values/encoded',label:'Encoded content',format:'text',writable:true,custom_field_key:key});}return current;}}});t.controller.next();await t.controller.capture(18);choosePurpose(t,'title');const recipe=clone(t.controller.state.recipe),source=clone(t.controller.state.design.source_reference);await t.controller.declareTermField(key,schema);assert.equal(t.controller.state.error,true);assert.match(t.controller.state.feedback,/was not returned/);assert.deepEqual(t.controller.state.recipe,recipe);assert.deepEqual(t.controller.state.design.source_reference,source);assert.deepEqual(t.controller.state.declaredTermFields,{});altered=true;await t.controller.declareTermField(key,schema);assert.equal(t.controller.state.error,true);assert.match(t.controller.state.feedback,/was not returned/);assert.deepEqual(t.controller.state.recipe,recipe);assert.deepEqual(t.controller.state.declaredTermFields,{});});
 await test('saved profiles normalize PHP empty declaration maps and reject nonempty arrays before replacement',async()=>{const id='00000000-0000-4000-8000-000000000018',current=categoryDesign();current.declared_term_fields=[];const recipe=ui.recipeFrom(current,'static');let invalidNext=false;const t=await categoryMounted({config:{profileId:id},request:async(path,payload)=>{if(path.startsWith('/profile?'))return {id,revision:3,resource_id:'taxonomy:product_cat',label:'Saved category',recipe,design:current};if(path==='/design'&&invalidNext)return {...clone(current),declared_term_fields:[{key:'field',schema:{type:'string'}}]};}});assert.equal(t.controller.state.error,false);assert.equal(Array.isArray(t.controller.state.declaredTermFields),false);assert.deepEqual(t.controller.state.declaredTermFields,{});const before=clone(t.controller.state.recipe);invalidNext=true;await t.controller.capture(18);assert.equal(t.controller.state.error,true);assert.match(t.controller.state.feedback,/could not be verified/);assert.deepEqual(t.controller.state.recipe,before);assert.equal(t.controller.state.id,id);assert.equal(t.controller.state.revision,3);});
